import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { projectsAPI, contractsAPI } from '../../services/api';
import { useAuth } from '../../context/AuthContext';
import AppLayout from '../../components/layout/AppLayout';

const StatCard = ({ icon, label, value, color='#F59E0B', sub }) => (
  <div className="card" style={{ display:'flex', alignItems:'center', gap:20 }}>
    <div style={{ width:52, height:52, borderRadius:12, background:`rgba(${color === '#F59E0B' ? '245,158,11' : color === '#10B981' ? '16,185,129' : '59,130,246'},0.15)`, display:'flex', alignItems:'center', justifyContent:'center', fontSize:24, flexShrink:0 }}>{icon}</div>
    <div>
      <p style={{ fontSize:13, color:'#6B7280', margin:0, fontFamily:'Barlow Condensed', fontWeight:600, letterSpacing:0.5, textTransform:'uppercase' }}>{label}</p>
      <p style={{ fontSize:32, fontFamily:'Bebas Neue', color, margin:'2px 0 0', letterSpacing:1 }}>{value}</p>
      {sub && <p style={{ fontSize:12, color:'#6B7280', margin:0 }}>{sub}</p>}
    </div>
  </div>
);

const statusLabel = { en_cours:'En cours', termine:'Terminé', suspendu:'Suspendu', planifie:'Planifié' };
const statusColor = { en_cours:'#10B981', termine:'#3B82F6', suspendu:'#EF4444', planifie:'#F59E0B' };
const typeLabel = { batiment:'Bâtiment', route:'Route', aep:'AEP', assainissement:'Assainissement', pont:'Pont', autre:'Autre' };

export default function DashboardPage() {
  const { user } = useAuth();
  const [projects, setProjects] = useState([]);
  const [contracts, setContracts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    Promise.all([projectsAPI.list(), contractsAPI.list()])
      .then(([p, c]) => { setProjects(p.data); setContracts(c.data); })
      .finally(() => setLoading(false));
  }, []);

  const activeProjects = projects.filter(p => p.status === 'en_cours').length;
  const completedContracts = contracts.filter(c => c.status === 'completed').length;

  return (
    <AppLayout>
      <div style={{ padding:'32px 40px' }} className="animate-fade-in">
        {/* Header */}
        <div style={{ marginBottom:32 }}>
          <p style={{ color:'#6B7280', fontSize:14, margin:'0 0 4px', fontFamily:'Barlow Condensed', letterSpacing:0.5 }}>
            {new Date().toLocaleDateString('fr-FR', { weekday:'long', year:'numeric', month:'long', day:'numeric' })}
          </p>
          <h1 style={{ fontFamily:'Bebas Neue', fontSize:42, color:'#fff', letterSpacing:1, margin:0 }}>
            Bonjour, <span style={{ color:'#F59E0B' }}>{user?.full_name?.split(' ')[0]}</span> 👋
          </h1>
          <p style={{ color:'#9CA3AF', fontSize:15, margin:'4px 0 0' }}>{user?.company_name}</p>
        </div>

        {/* Stats */}
        <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fit, minmax(200px, 1fr))', gap:20, marginBottom:40 }}>
          <StatCard icon="🏗️" label="Projets total" value={projects.length} color="#F59E0B" />
          <StatCard icon="⚡" label="En cours" value={activeProjects} color="#10B981" />
          <StatCard icon="📄" label="Contrats analysés" value={completedContracts} color="#3B82F6" />
          <StatCard icon="🏢" label="Entreprise" value={user?.company_name?.split(' ').slice(0,2).join(' ')} color="#F59E0B" />
        </div>

        {/* Quick actions */}
        <div style={{ marginBottom:40 }}>
          <h2 style={{ fontFamily:'Bebas Neue', fontSize:24, color:'#fff', letterSpacing:1, marginBottom:16 }}>Actions rapides</h2>
          <div style={{ display:'flex', gap:16, flexWrap:'wrap' }}>
            <Link to="/projects/new" className="btn btn-primary">+ Nouveau projet</Link>
            <Link to="/contracts/upload" className="btn btn-outline">📄 Analyser un contrat</Link>
          </div>
        </div>

        {/* Recent projects */}
        <div>
          <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:20 }}>
            <h2 style={{ fontFamily:'Bebas Neue', fontSize:24, color:'#fff', letterSpacing:1, margin:0 }}>Projets récents</h2>
            <Link to="/projects" style={{ color:'#F59E0B', fontSize:14, textDecoration:'none', fontFamily:'Barlow Condensed', fontWeight:600 }}>Voir tous →</Link>
          </div>

          {loading ? (
            <div style={{ textAlign:'center', padding:40 }}>
              <div style={{ width:32, height:32, border:'3px solid #F59E0B', borderTopColor:'transparent', borderRadius:'50%', animation:'spin 1s linear infinite', margin:'0 auto 12px' }} />
              <p style={{ color:'#6B7280' }}>Chargement...</p>
            </div>
          ) : projects.length === 0 ? (
            <div className="card" style={{ textAlign:'center', padding:48 }}>
              <div style={{ fontSize:48, marginBottom:16 }}>🏗️</div>
              <h3 style={{ fontFamily:'Bebas Neue', fontSize:24, color:'#fff', marginBottom:8 }}>Aucun projet</h3>
              <p style={{ color:'#6B7280', marginBottom:24 }}>Créez votre premier projet pour commencer</p>
              <Link to="/projects/new" className="btn btn-primary">Créer un projet</Link>
            </div>
          ) : (
            <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fill, minmax(300px, 1fr))', gap:16 }}>
              {projects.slice(0, 6).map(project => (
                <Link key={project.id} to={`/projects/${project.id}`} style={{ textDecoration:'none' }}>
                  <div className="card" style={{ cursor:'pointer', transition:'all 0.2s', ':hover':{ borderColor:'rgba(245,158,11,0.3)' } }}>
                    <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', marginBottom:12 }}>
                      <span style={{ fontSize:24 }}>{project.project_type === 'route' ? '🛣️' : project.project_type === 'aep' ? '💧' : project.project_type === 'pont' ? '🌉' : '🏗️'}</span>
                      <span className="badge" style={{ background:`rgba(${statusColor[project.status] === '#10B981' ? '16,185,129' : statusColor[project.status] === '#3B82F6' ? '59,130,246' : statusColor[project.status] === '#EF4444' ? '239,68,68' : '245,158,11'},0.15)`, color: statusColor[project.status] }}>
                        {statusLabel[project.status]}
                      </span>
                    </div>
                    <h3 style={{ fontFamily:'Barlow Condensed', fontSize:18, fontWeight:700, color:'#fff', margin:'0 0 6px' }}>{project.name}</h3>
                    <p style={{ fontSize:13, color:'#6B7280', margin:'0 0 12px' }}>📍 {project.location || 'Localisation non définie'}</p>
                    <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center' }}>
                      <span style={{ fontSize:12, color:'#9CA3AF', fontFamily:'Barlow Condensed' }}>{typeLabel[project.project_type]}</span>
                      <span style={{ fontSize:12, color:'#6B7280' }}>{project.contracts_count} contrat(s)</span>
                    </div>
                  </div>
                </Link>
              ))}
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}
